import{_ as e,o as r,c as a,ag as l}from"./chunks/framework.K4imGPUB.js";const b=JSON.parse('{"title":"拖拽库","description":"","frontmatter":{},"headers":[],"relativePath":"docs/engineering/前端/工具库/拖拽库.md","filePath":"docs/engineering/前端/工具库/拖拽库.md"}'),i={name:"docs/engineering/前端/工具库/拖拽库.md"};function n(d,t,o,u,h,g){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="拖拽库" tabindex="-1">拖拽库 <a class="header-anchor" href="#拖拽库" aria-label="Permalink to &quot;拖拽库&quot;">​</a></h1><h2 id="vue拖拽库" tabindex="-1">Vue拖拽库 <a class="header-anchor" href="#vue拖拽库" aria-label="Permalink to &quot;Vue拖拽库&quot;">​</a></h2><p>在 Vue 项目中实现拖拽排序、布局编辑、看板交互等功能是非常常见的需求。我给你整理了目前社区中最常用、最实用的 Vue 拖拽相关插件，涵盖列表拖拽、网格布局、缩放组件、动画交互等多个场景。</p><h3 id="📝-总结对比-vue拖拽库" tabindex="-1">📝 总结对比 Vue拖拽库 <a class="header-anchor" href="#📝-总结对比-vue拖拽库" aria-label="Permalink to &quot;📝 总结对比 Vue拖拽库&quot;">​</a></h3><table tabindex="0"><thead><tr><th>插件名</th><th>特点</th><th>Vue 3 支持</th><th>推荐指数</th><th>GitHub 链接</th></tr></thead><tbody><tr><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2FSortableJS%2Fvue.draggable.next" target="_blank" rel="noreferrer">Vue.Draggable</a></td><td>官方支持、功能全面</td><td>✅</td><td>⭐⭐⭐⭐⭐</td><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2FSortableJS%2Fvue.draggable.next" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fanish2690%2Fvue-draggable-next" target="_blank" rel="noreferrer">vue-draggable-next</a></td><td>拖拽排序、轻量封装</td><td>✅</td><td>⭐⭐⭐⭐</td><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fanish2690%2Fvue-draggable-next" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fjbaysolutions%2Fvue-grid-layout" target="_blank" rel="noreferrer">vue-grid-layout</a></td><td>拖拽网格布局，响应式</td><td>⚠️ 部分支持</td><td>⭐⭐⭐⭐</td><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fjbaysolutions%2Fvue-grid-layout" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fmauricius%2Fvue-draggable-resizable" target="_blank" rel="noreferrer">vue-draggable-resizable</a></td><td>拖拽 + 缩放，适合画布编辑器</td><td>✅</td><td>⭐⭐⭐⭐</td><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fmauricius%2Fvue-draggable-resizable" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fkutlugsahin%2Fvue-smooth-dnd" target="_blank" rel="noreferrer">vue-smooth-dnd</a></td><td>拖拽动画、嵌套列表</td><td>⚠️ 手动封装</td><td>⭐⭐⭐⭐</td><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fkutlugsahin%2Fvue-smooth-dnd" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fvueuse%2Fmotion" target="_blank" rel="noreferrer">@vueuse/motion</a></td><td>拖拽 + 动画 + 物理效果</td><td>✅</td><td>⭐⭐⭐⭐</td><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fvueuse%2Fmotion" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fhcg1023%2Fvue3-dnd" target="_blank" rel="noreferrer">vue3-dnd</a></td><td>拖拽逻辑控制，灵活性高</td><td>✅</td><td>⭐⭐⭐</td><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fhcg1023%2Fvue3-dnd" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fclauderic%2Fdnd-kit" target="_blank" rel="noreferrer">dnd-kit</a></td><td>高性能、复杂拖拽系统</td><td>⚠️ 手动封装</td><td>⭐⭐⭐⭐</td><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fclauderic%2Fdnd-kit" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2FSortableJS%2FSortable" target="_blank" rel="noreferrer">SortableJS</a></td><td>原生库，自由度高</td><td>✅</td><td>⭐⭐⭐</td><td><a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2FSortableJS%2FSortable" target="_blank" rel="noreferrer">GitHub</a></td></tr></tbody></table><h3 id="📦-一、列表拖拽排序类插件" tabindex="-1">📦 一、列表拖拽排序类插件 <a class="header-anchor" href="#📦-一、列表拖拽排序类插件" aria-label="Permalink to &quot;📦 一、列表拖拽排序类插件&quot;">​</a></h3><ol><li><p>Vue.Draggable（vue.draggable.next）实力推荐🤙</p><ul><li>✅ SortableJS 官方 Vue 封装，支持 Vue 2 和 Vue 3</li><li>💡 功能全面，社区活跃，文档丰富</li><li>📦 NPM：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fwww.npmjs.com%2Fpackage%2Fvuedraggable" target="_blank" rel="noreferrer">www.npmjs.com/package/vue…</a></li><li>🧾 GitHub：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2FSortableJS%2Fvue.draggable.next" target="_blank" rel="noreferrer">github.com/SortableJS/…</a></li><li>📖 文档：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fsortablejs.github.io%2Fvue.draggable.next%2F" target="_blank" rel="noreferrer">sortablejs.github.io/vue.draggab…</a></li></ul><p>适合场景：表单生成器、拖拽式菜单、列表排序</p></li><li><p>vue-draggable-next（推荐 Vue 3）</p><ul><li>✅ 基于 SortableJS 封装，Vue 3 官方推荐组件之一</li><li>✨ 支持拖拽排序、动画过渡、分组拖拽等</li><li>📦 NPM：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fwww.npmjs.com%2Fpackage%2Fvue-draggable-next" target="_blank" rel="noreferrer">www.npmjs.com/package/vue…</a></li><li>🧾 GitHub：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fanish2690%2Fvue-draggable-next" target="_blank" rel="noreferrer">github.com/anish2690/v…</a></li><li>📖 文档：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fvue-draggable-next.vercel.app%2F" target="_blank" rel="noreferrer">vue-draggable-next.vercel.app/</a> （打不开，等官方修复）</li></ul><p>适合场景：Trello 式看板、表格排序、动态组件列表</p></li><li><p>SortableJS（原生库）</p><ul><li>⚙️ 功能强大，支持原生 JS 拖拽排序</li><li>🧩 可与 Vue 手动集成（适合自定义封装）</li><li>📦 NPM：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fwww.npmjs.com%2Fpackage%2Fsortablejs" target="_blank" rel="noreferrer">www.npmjs.com/package/sor…</a></li><li>🧾 GitHub：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2FSortableJS%2FSortable" target="_blank" rel="noreferrer">github.com/SortableJS/…</a></li><li>📖 文档：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fsortablejs.github.io%2FSortable%2F" target="_blank" rel="noreferrer">sortablejs.github.io/Sortable/</a></li></ul><p>适合场景：需要与其他框架或原生项目结合使用</p></li></ol><h3 id="🧩-二、拖拽布局-网格系统类插件" tabindex="-1">🧩 二、拖拽布局 &amp; 网格系统类插件 <a class="header-anchor" href="#🧩-二、拖拽布局-网格系统类插件" aria-label="Permalink to &quot;🧩 二、拖拽布局 &amp; 网格系统类插件&quot;">​</a></h3><ol><li><p>vue-grid-layout</p><ul><li>🧱 类似 React Grid Layout，可构建响应式拖拽网格布局</li><li>✨ 支持缩放、拖拽、边界限制、持久化布局</li><li>📦 NPM：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fwww.npmjs.com%2Fpackage%2Fvue-grid-layout" target="_blank" rel="noreferrer">www.npmjs.com/package/vue…</a></li><li>🧾 GitHub：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fjbaysolutions%2Fvue-grid-layout" target="_blank" rel="noreferrer">github.com/jbaysolutio…</a></li><li>📖 文档：j<a href="https://link.juejin.cn/?target=https%3A%2F%2Fjbaysolutions.github.io%2Fvue-grid-layout%2F" target="_blank" rel="noreferrer">baysolutions.github.io/vue-grid-la…</a></li></ul><p>适合场景：仪表盘、组件可视化编辑器、后台布局系统</p></li><li><p>vue-draggable-resizable</p><ul><li>🔲 可拖拽 + 可缩放的组件（类似 PPT 块）</li><li>🎯 支持边界限制、吸附、最小尺寸等</li><li>📦 NPM：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fwww.npmjs.com%2Fpackage%2Fvue-draggable-resizable" target="_blank" rel="noreferrer">www.npmjs.com/package/vue…</a></li><li>🧾 GitHub：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fmauricius%2Fvue-draggable-resizable" target="_blank" rel="noreferrer">github.com/mauricius/v…</a></li><li>📖 示例：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fmauricius.github.io%2Fvue-draggable-resizable%2F" target="_blank" rel="noreferrer">mauricius.github.io/vue-draggab…</a></li></ul><p>适合场景：画布编辑器、图形排版、可视化搭建平台</p></li></ol><p>🎨 三、拖拽 + 动画交互插件</p><ol><li><p>vue-smooth-dnd</p><p>🎬 拖拽带动画，体验类似 Trello 🔁 支持嵌套、分组、拖拽预览 📦 NPM：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fwww.npmjs.com%2Fpackage%2Fvue-smooth-dnd" target="_blank" rel="noreferrer">www.npmjs.com/package/vue…</a> 🧾 GitHub：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fkutlugsahin%2Fvue-smooth-dnd" target="_blank" rel="noreferrer">github.com/kutlugsahin…</a> 📖 文档：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fkutlugsahin.github.io%2Fsmooth-dnd%2F" target="_blank" rel="noreferrer">kutlugsahin.github.io/smooth-dnd/</a></p><p>适合场景：任务看板、嵌套列表、拖拽分组</p></li><li><p>@vueuse/motion（VueUse Motion）</p><p>⚡ VueUse 出品，基于 Popmotion 实现 💫 支持拖拽、动画、物理效果（弹性、摩擦） 📦 NPM：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fwww.npmjs.com%2Fpackage%2F%40vueuse%2Fmotion" target="_blank" rel="noreferrer">www.npmjs.com/package/@vu…</a> 🧾 GitHub：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fvueuse%2Fmotion" target="_blank" rel="noreferrer">github.com/vueuse/moti…</a> 📖 官网：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fmotion.vueuse.org%2F" target="_blank" rel="noreferrer">motion.vueuse.org/</a></p><p>适合场景：组件拖拽动画、交互动效、页面动效增强</p></li></ol><h3 id="🔧-四、拖拽逻辑控制类插件" tabindex="-1">🔧 四、拖拽逻辑控制类插件 <a class="header-anchor" href="#🔧-四、拖拽逻辑控制类插件" aria-label="Permalink to &quot;🔧 四、拖拽逻辑控制类插件&quot;">​</a></h3><ol><li><p>vue3-dnd</p><p>🧠 类似 React DnD 的实现方式，更关注拖拽逻辑和行为 🧩 支持拖拽源、放置目标、拖拽预览等 📦 NPM：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fwww.npmjs.com%2Fpackage%2Fvue3-dnd" target="_blank" rel="noreferrer">www.npmjs.com/package/vue…</a> 🧾 GitHub：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fhcg1023%2Fvue3-dnd" target="_blank" rel="noreferrer">github.com/hcg1023/vue…</a></p><p>适合场景：需要自定义拖拽行为、构建复杂交互逻辑的项目</p></li><li><p>dnd-kit（需手动封装）</p><p>🚀 React 生态中最强大的拖拽引擎之一，性能极佳 🧱 支持拖拽层级、碰撞检测、键盘操作等 🌐 官网：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fdndkit.com%2F" target="_blank" rel="noreferrer">dndkit.com/</a> 🧾 GitHub：<a href="https://link.juejin.cn/?target=https%3A%2F%2Fgithub.com%2Fclauderic%2Fdnd-kit" target="_blank" rel="noreferrer">github.com/clauderic/d…</a></p><p>适合场景：构建复杂拖拽系统，如流程图、画布编辑器（需自行封装为 Vue 组件）</p></li></ol><h3 id="✅-使用建议-vue拖拽库" tabindex="-1">✅ 使用建议 Vue拖拽库 <a class="header-anchor" href="#✅-使用建议-vue拖拽库" aria-label="Permalink to &quot;✅ 使用建议 Vue拖拽库&quot;">​</a></h3><ul><li>如果你是做「列表排序」或「看板类」：推荐使用 vue-draggable-next 或 vue.draggable</li><li>如果你是做「仪表盘布局」：推荐 vue-grid-layout</li><li>如果你是做「画布编辑器」：推荐 vue-draggable-resizable</li><li>如果你想要「高级拖拽交互 + 动画」：推荐 vue-smooth-dnd 或 VueUse Motion</li><li>如果你想「高度自定义拖拽逻辑」：推荐 vue3-dnd 或 dnd-kit</li></ul><h2 id="react拖拽库" tabindex="-1">React拖拽库 <a class="header-anchor" href="#react拖拽库" aria-label="Permalink to &quot;React拖拽库&quot;">​</a></h2><p>在 React 项目中实现拖拽功能同样是一个常见需求。以下是目前社区中最流行、最实用的 React 拖拽相关库，涵盖了从简单列表拖拽到复杂拖拽系统的各种场景。</p><h3 id="📝-总结对比-react拖拽库" tabindex="-1">📝 总结对比 React拖拽库 <a class="header-anchor" href="#📝-总结对比-react拖拽库" aria-label="Permalink to &quot;📝 总结对比 React拖拽库&quot;">​</a></h3><table tabindex="0"><thead><tr><th>库名</th><th>特点</th><th>TypeScript 支持</th><th>推荐指数</th><th>GitHub 链接</th></tr></thead><tbody><tr><td><a href="https://github.com/atlassian/react-beautiful-dnd" target="_blank" rel="noreferrer">react-beautiful-dnd</a></td><td>Atlassian 出品，体验优秀</td><td>✅</td><td>⭐⭐⭐⭐⭐</td><td><a href="https://github.com/atlassian/react-beautiful-dnd" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td><a href="https://github.com/clauderic/dnd-kit" target="_blank" rel="noreferrer">dnd-kit</a></td><td>现代化、高性能、功能全面</td><td>✅</td><td>⭐⭐⭐⭐⭐</td><td><a href="https://github.com/clauderic/dnd-kit" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td><a href="https://github.com/react-dnd/react-dnd" target="_blank" rel="noreferrer">react-dnd</a></td><td>灵活、可扩展性强</td><td>✅</td><td>⭐⭐⭐⭐</td><td><a href="https://github.com/react-dnd/react-dnd" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td><a href="https://github.com/react-grid-layout/react-grid-layout" target="_blank" rel="noreferrer">react-grid-layout</a></td><td>网格布局拖拽</td><td>✅</td><td>⭐⭐⭐⭐</td><td><a href="https://github.com/react-grid-layout/react-grid-layout" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td><a href="https://github.com/react-grid-layout/react-draggable" target="_blank" rel="noreferrer">react-draggable</a></td><td>简单拖拽组件</td><td>✅</td><td>⭐⭐⭐</td><td><a href="https://github.com/react-grid-layout/react-draggable" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td><a href="https://github.com/SortableJS/react-sortablejs" target="_blank" rel="noreferrer">react-sortablejs</a></td><td>SortableJS 的 React 封装</td><td>✅</td><td>⭐⭐⭐</td><td><a href="https://github.com/SortableJS/react-sortablejs" target="_blank" rel="noreferrer">GitHub</a></td></tr></tbody></table><h3 id="📦-一、列表拖拽排序类库" tabindex="-1">📦 一、列表拖拽排序类库 <a class="header-anchor" href="#📦-一、列表拖拽排序类库" aria-label="Permalink to &quot;📦 一、列表拖拽排序类库&quot;">​</a></h3><ol><li><p>react-beautiful-dnd（强烈推荐）🤙</p><ul><li>✅ Atlassian 官方维护，质量有保证</li><li>💡 拖拽体验极佳，动画流畅</li><li>📦 NPM：<a href="https://www.npmjs.com/package/react-beautiful-dnd" target="_blank" rel="noreferrer">www.npmjs.com/package/react-beautiful-dnd</a></li><li>🧾 GitHub：<a href="https://github.com/atlassian/react-beautiful-dnd" target="_blank" rel="noreferrer">github.com/atlassian/react-beautiful-dnd</a></li><li>📖 文档：<a href="https://github.com/atlassian/react-beautiful-dnd" target="_blank" rel="noreferrer">github.com/atlassian/react-beautiful-dnd</a></li></ul><p>适合场景：看板、列表排序、任务管理</p></li><li><p>dnd-kit（新一代推荐）</p><ul><li>✅ 现代化、高性能、TypeScript 支持</li><li>✨ 支持触摸设备、键盘操作、无障碍</li><li>📦 NPM：<a href="https://www.npmjs.com/package/@dnd-kit/core" target="_blank" rel="noreferrer">www.npmjs.com/package/@dnd-kit/core</a></li><li>🧾 GitHub：<a href="https://github.com/clauderic/dnd-kit" target="_blank" rel="noreferrer">github.com/clauderic/dnd-kit</a></li><li>📖 文档：<a href="https://dndkit.com" target="_blank" rel="noreferrer">dndkit.com</a></li></ul><p>适合场景：复杂拖拽系统、自定义拖拽逻辑</p></li></ol><h3 id="🧩-二、拖拽布局-网格系统类库" tabindex="-1">🧩 二、拖拽布局 &amp; 网格系统类库 <a class="header-anchor" href="#🧩-二、拖拽布局-网格系统类库" aria-label="Permalink to &quot;🧩 二、拖拽布局 &amp; 网格系统类库&quot;">​</a></h3><ol><li><p>react-grid-layout</p><ul><li>🧱 响应式网格布局系统</li><li>✨ 支持拖拽、缩放、自动布局</li><li>📦 NPM：<a href="https://www.npmjs.com/package/react-grid-layout" target="_blank" rel="noreferrer">www.npmjs.com/package/react-grid-layout</a></li><li>🧾 GitHub：<a href="https://github.com/react-grid-layout/react-grid-layout" target="_blank" rel="noreferrer">github.com/react-grid-layout/react-grid-layout</a></li><li>📖 文档：<a href="https://react-grid-layout.github.io/react-grid-layout" target="_blank" rel="noreferrer">react-grid-layout.github.io/react-grid-layout</a></li></ul><p>适合场景：仪表盘、可视化编辑器、后台布局</p></li><li><p>react-draggable</p><ul><li>🔲 简单易用的拖拽组件</li><li>🎯 支持网格对齐、边界限制</li><li>📦 NPM：<a href="https://www.npmjs.com/package/react-draggable" target="_blank" rel="noreferrer">www.npmjs.com/package/react-draggable</a></li><li>🧾 GitHub：<a href="https://github.com/react-grid-layout/react-draggable" target="_blank" rel="noreferrer">github.com/react-grid-layout/react-draggable</a></li></ul><p>适合场景：简单拖拽需求、弹窗拖拽</p></li></ol><h3 id="🔧-三、高级拖拽系统类库" tabindex="-1">🔧 三、高级拖拽系统类库 <a class="header-anchor" href="#🔧-三、高级拖拽系统类库" aria-label="Permalink to &quot;🔧 三、高级拖拽系统类库&quot;">​</a></h3><ol><li><p>react-dnd</p><ul><li>🧠 基于 HTML5 拖放 API</li><li>🧩 高度可定制，支持复杂拖拽逻辑</li><li>📦 NPM：<a href="https://www.npmjs.com/package/react-dnd" target="_blank" rel="noreferrer">www.npmjs.com/package/react-dnd</a></li><li>🧾 GitHub：<a href="https://github.com/react-dnd/react-dnd" target="_blank" rel="noreferrer">github.com/react-dnd/react-dnd</a></li><li>📖 文档：<a href="https://react-dnd.github.io/react-dnd" target="_blank" rel="noreferrer">react-dnd.github.io/react-dnd</a></li></ul><p>适合场景：复杂拖拽系统、自定义拖拽行为</p></li><li><p>react-sortablejs</p><ul><li>⚙️ SortableJS 的 React 封装</li><li>🎯 功能全面，兼容性好</li><li>📦 NPM：<a href="https://www.npmjs.com/package/react-sortablejs" target="_blank" rel="noreferrer">www.npmjs.com/package/react-sortablejs</a></li><li>🧾 GitHub：<a href="https://github.com/SortableJS/react-sortablejs" target="_blank" rel="noreferrer">github.com/SortableJS/react-sortablejs</a></li></ul><p>适合场景：需要 SortableJS 功能的 React 项目</p></li></ol><h3 id="✅-使用建议-react拖拽库" tabindex="-1">✅ 使用建议 React拖拽库 <a class="header-anchor" href="#✅-使用建议-react拖拽库" aria-label="Permalink to &quot;✅ 使用建议 React拖拽库&quot;">​</a></h3><ul><li>如果你是做「列表排序」或「看板类」：推荐使用 react-beautiful-dnd</li><li>如果你是做「现代化应用」：推荐使用 dnd-kit</li><li>如果你是做「仪表盘布局」：推荐使用 react-grid-layout</li><li>如果你是做「简单拖拽」：推荐使用 react-draggable</li><li>如果你需要「高度自定义」：推荐使用 react-dnd</li><li>如果你需要「SortableJS 功能」：推荐使用 react-sortablejs</li></ul>',27)])])}const s=e(i,[["render",n]]);export{b as __pageData,s as default};
